        { heading: "不同级比较", body: "比较级 + als。", examples: [{ de: "Sie ist älter als ich.", zh: "她比我大。" }, { de: "Der Zug ist schneller als der Bus.", zh: "火车比公交快。" }] },
        { heading: "最高级", body: "am + 形容词 -sten。", examples: [{ de: "Das ist der schnellste Weg.", zh: "这是最快的路。" }, { de: "Sie läuft am schnellsten.", zh: "她跑得最快。" }] }
